action.filter:
any(
            all(selected_tile=${TILE_TRAPDOOR_WIDE},prev_tile=${TILE_TRAPDOOR_WIDE}),
            all(
                any(
                    selected_tile=${TILE_TRAPDOOR_SIDE_RIGHT},selected_tile=${TILE_TRAPDOOR_SIDE_LEFT}
                ),
                all(
                    any(
                        prev_tile=${TILE_TRAPDOOR_WIDE},prev_tile=${TILE_TRAPDOOR_SIDE_RIGHT},prev_tile=${TILE_TRAPDOOR_SIDE_LEFT}
                    ),
                    any(side_distance=2..,side_distance=..-2)
                )
            )
        )
